using namespace std;
vector&lt;int&gt; build_spf(int mx) {
vector&lt;int&gt; spf(mx, 0);
for (int i = 2; i &lt; mx; ++i) {
if (spf[i] != 0) continue;
spf[i] = i;
for (long long j = 1LL * i * i; j &lt; mx; j += i) {
if (spf[j] == 0) {
spf[j] = i;
}
}
}
return spf;
}
vector&lt;int&gt; distinct_prime_factors(int x, const vector&lt;int&gt;&amp; spf) {
vector&lt;int&gt; primes;
while (x &gt; 1) {
int p = spf[x];
primes.push_back(p);
while (x % p == 0) {
x /= p;
}
}
return primes;
}
