C++<pre><code>#include &lt;bits/stdc++.h&gt;
using namespace std;
class SegmentTree {
public:
int n;
vector&lt;int&gt; sum;
SegmentTree(vector&lt;int&gt;&amp; arr) {
n = arr.size();
sum.assign(4 * n, 0);
build(1, 0, n - 1, arr);
}
void build(int p, int l, int r, vector&lt;int&gt;&amp; arr) {
if (l == r) {
sum[p] = arr[l];
return;
}
int mid = (l + r) / 2;
build(p &lt;&lt; 1, l, mid, arr);
build(p &lt;&lt; 1 | 1, mid + 1, r, arr);
sum[p] = sum[p &lt;&lt; 1] + sum[p &lt;&lt; 1 | 1];
}
void update(int p, int l, int r, int k, int v) {
if (l == r) {
sum[p] = v;
return;
}
int mid = (l + r) / 2;
if (k &lt;= mid)
update(p &lt;&lt; 1, l, mid, k, v);
else
update(p &lt;&lt; 1 | 1, mid + 1, r, k, v);
sum[p] = sum[p &lt;&lt; 1] + sum[p &lt;&lt; 1 | 1];
}
int query(int p, int l, int r, int ql, int qr) {
if (qr &lt; l || r &lt; ql) return 0;
if (ql &lt;= l &amp;&amp; r &lt;= qr) {
return sum[p];
}
int mid = (l + r) / 2;
int a = query(p &lt;&lt; 1, l, mid, ql, qr);
int b = query(p &lt;&lt; 1 | 1, mid + 1, r, ql, qr);
return a + b;
}
};
