C++<pre><code>#include &lt;bits/stdc++.h&gt;
using namespace std;
class SegmentTree {
public:
int n;
vector&lt;int&gt; st, lazy;
vector&lt;bool&gt; is_lazy;
SegmentTree(int n) {
this-&gt;n = n;
st.assign(4 * n, 0);
lazy.assign(4 * n, 0);
is_lazy.assign(4 * n, false);
}
void apply(int p, int v) {
lazy[p] = v;
st[p] = v;
is_lazy[p] = true;
}
void push(int p) {
if (!is_lazy[p]) return;
apply(p &lt;&lt; 1, lazy[p]);
apply(p &lt;&lt; 1 | 1, lazy[p]);
is_lazy[p] = false;
}
void pull(int p) {
st[p] = max(st[p &lt;&lt; 1], st[p &lt;&lt; 1 | 1]);
}
void update(int p, int l, int r, int ql, int qr, int val) {
if (ql &lt;= l &amp;&amp; r &lt;= qr) {
apply(p, val);
return;
}
if (qr &lt; l || r &lt; ql) return;
push(p);
int mid = (l + r) / 2;
update(p &lt;&lt; 1, l, mid, ql, qr, val);
update(p &lt;&lt; 1 | 1, mid + 1, r, ql, qr, val);
pull(p);
}
int query(int p, int l, int r, int ql, int qr) {
if (ql &lt;= l &amp;&amp; r &lt;= qr) {
return st[p];
}
if (qr &lt; l || r &lt; ql) return 0;
push(p);
int mid = (l + r) / 2;
int a = query(p &lt;&lt; 1, l, mid, ql, qr);
int b = query(p &lt;&lt; 1 | 1, mid + 1, r, ql, qr);
return max(a, b);
}
};
