C++<pre><code>#include &lt;bits/stdc++.h&gt;
using namespace std;
using ll = long long;
using pll = pair&lt;ll, ll&gt;;
const ll mod = 998244353;
class SegmentTree {
public:
vector&lt;ll&gt; sum, sum2, lazy;
SegmentTree(int n) {
sum.assign(4 * n, 0);
sum2.assign(4 * n, 0);
lazy.assign(4 * n, 0);
}
ll norm(ll x) {
x %= mod;
if (x &lt; 0) x += mod;
return x;
}
void apply(int p, int l, int r, ll v) {
v = norm(v);
ll len = r - l + 1;
sum2[p] = (
sum2[p]
+ 2LL * v % mod * sum[p] % mod
+ len % mod * v % mod * v % mod
) % mod;
sum[p] = (sum[p] + len % mod * v) % mod;
lazy[p] = (lazy[p] + v) % mod;
}
void push(int p, int l, int r) {
if (lazy[p] == 0) return;
int mid = (l + r) / 2;
apply(p &lt;&lt; 1, l, mid, lazy[p]);
apply(p &lt;&lt; 1 | 1, mid + 1, r, lazy[p]);
lazy[p] = 0;
}
void pull(int p) {
sum[p] = (sum[p &lt;&lt; 1] + sum[p &lt;&lt; 1 | 1]) % mod;
sum2[p] = (sum2[p &lt;&lt; 1] + sum2[p &lt;&lt; 1 | 1]) % mod;
}
void range_add(int p, int l, int r, int ql, int qr, ll v) {
if (qr &lt; l || r &lt; ql) return;
if (ql &lt;= l &amp;&amp; r &lt;= qr) {
apply(p, l, r, v);
return;
}
push(p, l, r);
int mid = (l + r) / 2;
range_add(p &lt;&lt; 1, l, mid, ql, qr, v);
range_add(p &lt;&lt; 1 | 1, mid + 1, r, ql, qr, v);
pull(p);
}
pll query(int p, int l, int r, int ql, int qr) {
if (qr &lt; l || r &lt; ql) return {0, 0};
if (ql &lt;= l &amp;&amp; r &lt;= qr) {
return {sum[p], sum2[p]};
}
push(p, l, r);
int mid = (l + r) / 2;
auto L = query(p &lt;&lt; 1, l, mid, ql, qr);
auto R = query(p &lt;&lt; 1 | 1, mid + 1, r, ql, qr);
return {
(L.first + R.first) % mod,
(L.second + R.second) % mod
};
}
};
</code></pre>

C++<pre><code>#include &lt;bits/stdc++.h&gt;
using namespace std;
class Mo {
public:
struct Query {
int l, r, id;
};
int n;
int blockSize;
vector&lt;Query&gt; queries;
Mo(int _n, int q = 0) {
n = _n;
blockSize = (int)sqrt(n) + 1;
queries.reserve(q);
}
void addQuery(int l, int r, int id) {
queries.push_back({l, r, id});
}
template&lt;class Add, class Remove, class Answer&gt;
void run(Add add, Remove remove, Answer answer) {
sort(queries.begin(), queries.end(), [&amp;](const Query&amp; a, const Query&amp; b) {
int ba = a.l / blockSize;
int bb = b.l / blockSize;
if (ba != bb) return ba &lt; bb;
if (ba &amp; 1) return a.r &gt; b.r;
return a.r &lt; b.r;
});
int L = 0;
int R = -1;
for (auto&amp; q : queries) {
while (q.l &lt; L) add(--L);
while (R &lt; q.r) add(++R);
while (q.l &gt; L) remove(L++);
while (R &gt; q.r) remove(R--);
answer(q.id);
}
}
};
</code></pre>

C++<pre><code>#include &lt;bits/stdc++.h&gt;
using namespace std;
using ll = long long;
class SqrtDcm {
public:
int n, b, c;
vector&lt;ll&gt; arr, lazy;
vector&lt;unordered_map&lt;ll, int&gt;&gt; bucket;
SqrtDcm(vector&lt;int&gt;&amp; nums) {
n = nums.size();
b = sqrt(n) + 1;
c = (n + b - 1) / b;
arr.resize(n);
lazy.assign(c, 0);
bucket.resize(c);
for (int i = 0; i &lt; n; ++i) {
arr[i] = nums[i];
}
for (int i = 0; i &lt; c; ++i) {
rebuild(i);
}
}
int bl(int i) {
return i * b;
}
int br(int i) {
return min(n - 1, (i + 1) * b - 1);
}
void rebuild(int i) {
bucket[i].clear();
for (int j = bl(i); j &lt;= br(i); ++j) {
++bucket[i][arr[j]];
}
}
void rangeadd(int l, int r, ll v) {
int lb = l / b;
int rb = r / b;
if (lb == rb) {
for (int i = l; i &lt;= r; ++i) {
arr[i] += v;
}
rebuild(lb);
return;
}
for (int i = l; i &lt;= br(lb); ++i) {
arr[i] += v;
}
rebuild(lb);
for (int i = lb + 1; i &lt; rb; ++i) {
lazy[i] += v;
}
for (int i = bl(rb); i &lt;= r; ++i) {
arr[i] += v;
}
rebuild(rb);
}
int query(ll t) {
int ans = 0;
for (int i = 0; i &lt; c; ++i) {
ll raw = t - lazy[i];
auto it = bucket[i].find(raw);
if (it != bucket[i].end()) {
ans += it-&gt;second;
}
}
return ans;
}
};
</code></pre>

C++<pre><code>#include &lt;bits/stdc++.h&gt;
using namespace std;
using ll = long long;
using ull = unsigned long long;
ll rnd(ll l, ll r) {
static mt19937_64 rng(
chrono::steady_clock::now().time_since_epoch().count()
);
return uniform_int_distribution&lt;ll&gt;(l, r)(rng);
}
class Hash {
public:
static constexpr ll mod1 = 1000000007;
static constexpr ll mod2 = 1000000009;
static ll base1;
static ll base2;
vector&lt;ll&gt; h1, p1, h2, p2;
Hash(const vector&lt;int&gt;&amp; s) {
int n = s.size();
h1.assign(n + 1, 0);
p1.assign(n + 1, 1);
h2.assign(n + 1, 0);
p2.assign(n + 1, 1);
for (int i = 0; i &lt; n; ++i) {
ll x = s[i] + 1007;
h1[i + 1] = (h1[i] * base1 + x) % mod1;
p1[i + 1] = p1[i] * base1 % mod1;
h2[i + 1] = (h2[i] * base2 + x) % mod2;
p2[i + 1] = p2[i] * base2 % mod2;
}
}
ull query(int l, int r) {
++l;
++r;
ll val1 = (h1[r] - h1[l - 1] * p1[r - l + 1] % mod1 + mod1) % mod1;
ll val2 = (h2[r] - h2[l - 1] * p2[r - l + 1] % mod2 + mod2) % mod2;
return ((ull)val1 &lt;&lt; 32) | (ull)val2;
}
};
ll Hash::base1 = rnd(256, Hash::mod1 - 2);
ll Hash::base2 = rnd(256, Hash::mod2 - 2);
