C++<pre><code>#include &lt;bits/stdc++.h&gt;
using namespace std;
vector&lt;int&gt; prefix_function(const string&amp; pattern) {
int n = pattern.size();
vector&lt;int&gt; pi(n, 0);
for (int i = 1; i &lt; n; ++i) {
int j = pi[i - 1];
while (j &gt; 0 &amp;&amp; pattern[i] != pattern[j]) {
j = pi[j - 1];
}
if (pattern[i] == pattern[j]) {
++j;
}
pi[i] = j;
}
return pi;
}
vector&lt;int&gt; covered_by_matches(const string&amp; text, const string&amp; pattern) {
int n = text.size();
int m = pattern.size();
vector&lt;int&gt; cover(n, 0);
if (m == 0) return cover;
vector&lt;int&gt; pi = prefix_function(pattern);
vector&lt;int&gt; diff(n + 1, 0);
int j = 0;
for (int i = 0; i &lt; n; ++i) {
while (j &gt; 0 &amp;&amp; text[i] != pattern[j]) {
j = pi[j - 1];
}
if (text[i] == pattern[j]) {
++j;
}
if (j == m) {
int start = i - m + 1;
++diff[start];
--diff[i + 1];
j = pi[j - 1];
}
}
int cur = 0;
for (int i = 0; i &lt; n; ++i) {
cur += diff[i];
cover[i] = cur &gt; 0;
}
return cover;
}
