vector&lt;int&gt; z(n, 0);
int l = 0;
int r = 0;
for (int i = 1; i &lt; n; ++i) {
if (i &lt;= r) {
z[i] = min(r - i + 1, z[i - l]);
}
while (i + z[i] &lt; n &amp;&amp; s[z[i]] == s[i + z[i]]) {
++z[i];
}
if (i + z[i] - 1 &gt; r) {
l = i;
r = i + z[i] - 1;
}
}
